def build_contents():
    records = scenarios()
    if len(records) != 35:
        raise ValueError("Нужно ровно 35 новых сценариев")
    cases, labels, notes = zip(*records)
    ids = [case["case_id"] for case in cases]
    if len(set(ids)) != 35 or ids != [label["case_id"] for label in labels]:
        raise ValueError("ID кейсов и эталонов должны совпадать и быть уникальными")
    if Counter(label["document_type"] for label in labels) != {"invoice_draft": 20, "transfer_draft": 10, "none": 5}:
        raise ValueError("Ожидаются 20 счетов, 10 переводов и 5 none")
    if Counter(case["split"] for case in cases) != {"dev": 18, "test": 17}:
        raise ValueError("Разбиение должно быть dev=18/test=17")
    for case, label, _ in records:
        parsed = InputCase.model_validate(case)
        validate_messages(parsed.messages)
        LABEL_ADAPTER.validate_python(label)
        if len(parsed.messages) < 7 or sum(len(m.text) for m in parsed.messages) < 1100:
            raise ValueError("Слишком короткий диалог: " + parsed.case_id)
        user_ids = {m.id for m in parsed.messages if m.role == "user"}
        for name, field in label["fields"].items():
            if not set(field["evidence"]) <= user_ids:
                raise ValueError("Непользовательский источник: " + parsed.case_id)
            if field["status"] == "fillable" and _invalid_format(name, field["value"]):
                raise ValueError("Неверный формат эталона: " + parsed.case_id + "." + name)
    encode = lambda rows: "".join(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n" for row in rows)
    lengths = [sum(len(m["text"]) for m in case["messages"]) for case in cases]
    catalogue = [
        "# Tricky35: длинные диалоги с несколькими ловушками", "",
        "35 новых синтетических сценариев T001–T035: 20 счетов, 10 переводов себе и 5 none.",
        "Разбиение dev=18/test=17 задано до прогонов; модели для подготовки данных не вызывались.",
        "Эталоны написаны вручную, источники — только реплики пользователя. Реквизиты вымышлены.",
        "Это стресс-набор, а не репрезентативная выборка обращений и не доказательство качества модели.",
        "Строгая оценка источников требует ровно указанных ID; альтернативный достаточный набор ID может отличаться.",
        "При исправлении позиции evidence объединяет актуальные источники её атрибутов, без архивных значений.",
        "При скидке на весь счёт цены в строках сохраняются; скидка применяется только к amount_rub.",
        "Для missing evidence пуст; факт отзыва значения описан в диалоге, но отсутствующее значение не заполняется.",
        "Проценты НДС берутся только из явно указанной актуальной ставки; единицы копируются в исходной форме.",
        f"Длина диалогов: {min(lengths)}–{max(lengths)} символов, в среднем {sum(lengths) // len(lengths)}.", "",
        "| ID | Split | Тип | Реплик | Символов | Ловушки и ключевые решения |",
        "| --- | --- | --- | ---: | ---: | --- |",
    ]
    for case, label, note in records:
        catalogue.append(f"| {case['case_id']} | {case['split']} | {label['document_type']} | "
                         f"{len(case['messages'])} | {sum(len(m['text']) for m in case['messages'])} | {note} |")
    catalogue += ["", "Сборка: `uv run --locked python -m scripts.build_tricky35_dataset`.",
                  "Проверка: `uv run --locked python -m scripts.build_tricky35_dataset --check`.", ""]
    return {"cases_tricky35.jsonl": encode(cases), "labels_tricky35.jsonl": encode(labels),
            "tricky35.md": "\n".join(catalogue)}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="Проверить файлы без перезаписи")
    args = parser.parse_args()
    for name, contents in build_contents().items():
        path = DATA / name
        if args.check:
            if not path.is_file() or path.read_text(encoding="utf-8") != contents:
                raise SystemExit(f"{name} не соответствует scripts.build_tricky35_dataset")
        else:
            path.write_text(contents, encoding="utf-8")
    print("tricky35: 35 новых кейсов, dev=18/test=17; 20 счетов, 10 переводов, 5 none. API не вызывались.")


if __name__ == "__main__":
    main()
